import { existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import type Database from 'better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { readMigrationFiles, type MigrationMeta } from 'drizzle-orm/migrator';
import type { Db } from './client';
import { DEFAULT_KEEP_SNAPSHOTS, takeSnapshot } from './snapshot';

/**
 * Versioned migrations generated by `pnpm db:generate`. Resolved next to this module:
 * `src/db/migrations` from sources, `dist/migrations` in the bundle (copied by build.mjs).
 */
export const MIGRATIONS_DIR = fileURLToPath(new URL('./migrations', import.meta.url));
const MIGRATIONS_TABLE = '__drizzle_migrations';

/** Reads the migration journal; a folder without one means "no migrations yet". */
export function readMigrations(folder: string = MIGRATIONS_DIR): MigrationMeta[] {
  if (!existsSync(path.join(folder, 'meta', '_journal.json'))) {
    return [];
  }
  return readMigrationFiles({ migrationsFolder: folder });
}

function lastAppliedAt(sqlite: Database.Database): number | null {
  const table = sqlite
    .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?")
    .get(MIGRATIONS_TABLE);
  if (table === undefined) {
    return null;
  }
  const row = sqlite
    .prepare(`SELECT created_at AS at FROM "${MIGRATIONS_TABLE}" ORDER BY created_at DESC LIMIT 1`)
    .get() as { at: number | string } | undefined;
  return row === undefined ? null : Number(row.at);
}

/** Migrations not yet applied (same rule as Drizzle's migrator: newer than the last one). */
export function pendingMigrations(
  sqlite: Database.Database,
  migrations: readonly MigrationMeta[],
): MigrationMeta[] {
  const last = lastAppliedAt(sqlite);
  return migrations.filter((m) => last === null || last < m.folderMillis);
}

export interface MigrateOptions {
  /** Where pre-migration snapshots go (`DATA_DIR/snapshots`). */
  readonly snapshotDir: string;
  readonly migrationsFolder?: string;
  readonly keepSnapshots?: number;
  readonly now?: Date;
}

export interface MigrateResult {
  readonly applied: number;
  /** Snapshot taken before applying, or null (nothing pending, or a brand-new database). */
  readonly snapshot: string | null;
}

/**
 * Applies pending migrations in one transaction. If the database already has applied
 * migrations (i.e. holds data), a snapshot is taken first so a bad migration can be undone.
 */
export async function runMigrations(db: Db, options: MigrateOptions): Promise<MigrateResult> {
  const folder = options.migrationsFolder ?? MIGRATIONS_DIR;
  const migrations = readMigrations(folder);
  const pending = pendingMigrations(db.$client, migrations);
  if (pending.length === 0) {
    return { applied: 0, snapshot: null };
  }
  const hasHistory = lastAppliedAt(db.$client) !== null;
  const snapshot = hasHistory
    ? await takeSnapshot(db.$client, options.snapshotDir, {
        keep: options.keepSnapshots ?? DEFAULT_KEEP_SNAPSHOTS,
        ...(options.now ? { now: options.now } : {}),
      })
    : null;
  migrate(db, { migrationsFolder: folder });
  console.info(
    `Applied ${pending.length} migration(s)` + (snapshot ? `; snapshot: ${snapshot}` : ''),
  );
  return { applied: pending.length, snapshot };
}
